import Hatchet from "@hatchet-dev/typescript-sdk";

const runId = process.env.ZEALT_RUN_ID ?? "default";

export const hatchet = new Hatchet();

export const workflow = hatchet.workflow<{}, {
  step1: { text: string };
  step2: { text: string };
  step3: { final: string };
}>({
  name: `linear-dag-${runId}`,
});

export const step1 = workflow.task({
  name: "step1",
  fn: async (_input, _ctx) => {
    return { text: "hello" };
  },
});

export const step2 = workflow.task({
  name: "step2",
  parents: [step1],
  fn: async (_input, ctx) => {
    const parent = await ctx.parentOutput(step1);
    return { text: parent.text + " world" };
  },
});

export const step3 = workflow.task({
  name: "step3",
  parents: [step2],
  fn: async (_input, ctx) => {
    const parent = await ctx.parentOutput(step2);
    return { final: parent.text + "!" };
  },
});

import { hatchet, workflow } from "./workflow.js";

const runId = process.env.ZEALT_RUN_ID ?? "default";

async function main() {
  const worker = await hatchet.worker(`linear-dag-worker-${runId}`, {
    workflows: [workflow],
  });

  await worker.start();
}

main().catch((err) => {
  console.error("Worker error:", err);
  process.exit(1);
});

import fs from "fs";
import { workflow } from "./workflow.js";

async function main() {
  const result = await workflow.run({});

  const step3Output = result.step3;

  console.log("Workflow completed. step3 output:", step3Output);

  fs.writeFileSync("/tmp/result.json", JSON.stringify(step3Output));

  console.log("Result written to /tmp/result.json");
}

main().catch((err) => {
  console.error("Runner error:", err);
  process.exit(1);
});

